<link rel="stylesheet" href="<?=legacy_base_url('assets/css/marketplace-customer-admin.css?v=15')?>"><main class="admin-main mp-admin"><header class="admin-topbar page-topbar"><button class="sidebar-toggle" id="sidebarToggle"><i class="bi bi-list"></i></button><div class="topbar-title"><h1>Health, Activity & Logs</h1><p>Monitoring Marketplace, API dan cron dalam satu halaman.</p></div></header><section class="mp-stat-grid"><div class="mp-stat"><i class="bi bi-truck"></i><span>RajaOngkir</span><strong><?=$rajaOk?'READY':'SETUP'?></strong><small><?=$rajaOk?'API key terisi':'Belum dikonfigurasi'?></small></div><div class="mp-stat"><i class="bi bi-wallet2"></i><span>Pakasir</span><strong><?=$pakOk?'READY':'SETUP'?></strong><small><?=$pakOk?'API key marketplace terisi':'Belum dikonfigurasi'?></small></div><div class="mp-stat"><i class="bi bi-whatsapp"></i><span>WA Gateway</span><strong><?=$waOk?'READY':'SETUP'?></strong><small><?=$waOk?'Token gateway terisi':'Belum dikonfigurasi'?></small></div><div class="mp-stat"><i class="bi bi-clock-history"></i><span>Last Cron</span><strong><?=$lastCron?e(strtoupper($lastCron['status'])):'BELUM'?></strong><small><?=$lastCron?e(date('d/m/Y H:i',strtotime($lastCron['started_at']))):'Belum ada log'?></small></div></section><section class="mp-panel"><div class="mp-filter-row"><a class="mp-btn soft <?=$tab==='activity'?'active':''?>" href="?tab=activity">Activity</a><a class="mp-btn soft <?=$tab==='api'?'active':''?>" href="?tab=api">API</a><a class="mp-btn soft <?=$tab==='cron'?'active':''?>" href="?tab=cron">Cron</a></div><div class="table-premium-card"><table class="premium-table"><thead><?php if($tab==='activity'):?><tr><th>Waktu</th><th>User</th><th>Aksi</th><th>Entity</th><th>Deskripsi</th><th>IP</th></tr><?php elseif($tab==='api'):?><tr><th>Waktu</th><th>Provider</th><th>Event</th><th>Status</th><th>Error</th></tr><?php else:?><tr><th>Mulai</th><th>Job</th><th>Status</th><th>Processed</th><th>Durasi</th><th>Error</th></tr><?php endif;?></thead><tbody><?php foreach($rows as $r):if($tab==='activity'):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['user_name']?:'System')?></td><td><b><?=e($r['action'])?></b></td><td><?=e(($r['entity_type']?:'-').($r['entity_id']?' #'.$r['entity_id']:''))?></td><td><?=e($r['description']?:'-')?></td><td><?=e($r['ip_address']?:'-')?></td></tr><?php elseif($tab==='api'):?><tr><td><?=e($r['created_at'])?></td><td><b><?=e($r['provider'])?></b></td><td><?=e($r['event']?:'-')?></td><td><?=$r['success']?'OK':'FAIL'?> <?=e($r['http_status']?:'')?></td><td><?=e($r['error_message']?:'-')?></td></tr><?php else:?><tr><td><?=e($r['started_at'])?></td><td><b><?=e($r['job_name'])?></b></td><td><?=e($r['status'])?></td><td><?=e($r['processed'])?></td><td><?=e($r['duration_ms'])?> ms</td><td><?=e($r['error_message']?:'-')?></td></tr><?php endif;endforeach;?></tbody></table></div></section></main><?php require __DIR__.'/../../layouts/admin-footer.php';?>
